    "kb": [
      {"pattern": "分离定律|孟德尔第一定律", "answer": "控制一对相对性状的等位基因在形成配子时彼此分离，分别进入不同的配子中。**细胞学基础**：减数第一次分裂后期同源染色体分离。"},
      {"pattern": "自由组合定律|孟德尔第二定律", "answer": "控制不同性状的非等位基因在形成配子时自由组合。**细胞学基础**：减数第一次分裂后期非同源染色体自由组合。"},
      {"pattern": "测交|验证实验", "answer": "用隐性纯合子与待测个体杂交，根据后代性状分离比推断待测个体的基因型。例如 `Dd × dd → 1:1`。"},
      {"pattern": "显性|隐性", "answer": "显性性状：F1 表现出来的性状（如高茎）；隐性性状：F1 未表现、F2 重新出现的性状（如矮茎）。"},
      {"pattern": "基因型|表现型", "answer": "基因型：个体的遗传组成（如 `DD`、`Dd`、`dd`）；表现型：个体实际表现出的性状（如高茎、矮茎）。"},
      {"pattern": "乘法原理|加法原理", "answer": "乘法原理：两个独立事件同时发生的概率 = 各自概率的乘积。加法原理：互斥事件至少一个发生的概率 = 各自概率之和。"}
    ]
  },
