    {
      "id": "why-pea",
      "kind": "content",
      "eyebrow": "孟德尔的实验与推理",
      "headline": "为什么是豌豆？",
      "lead": "孟德尔选择豌豆，因为它严格自花传粉、相对性状明显、易于栽培和统计。",
      "notes": "豌豆是自花传粉、闭花授粉植物，自然状态下多为纯种。有 7 对易于区分的相对性状（如高茎 vs 矮茎、圆粒 vs 皱粒）。生长周期短，子代数量多，便于统计。这些特点让孟德尔能排除干扰，聚焦于性状的传递规律。",
      "blocks": [
        {
          "id": "b_pea_advantages",
          "type": "list",
          "intent": "列出豌豆作为实验材料的 4 个关键优点：自花传粉、相对性状、易栽培、子代多。"
        }
      ]
    },
    {
      "id": "monohybrid-experiment",
      "kind": "content",
      "eyebrow": "孟德尔的实验与推理",
      "headline": "一对相对性状的杂交实验",
      "lead": "高茎豌豆与矮茎豌豆杂交，F1 全为高茎；F1 自交，F2 出现高茎:矮茎 ≈ 3:1。",
      "notes": "孟德尔用纯种高茎（DD）和纯种矮茎（dd）杂交，F1 全部是高茎（Dd）。F1 自交，F2 中高茎与矮茎的比例约为 3:1。这个比例不是偶然的——孟德尔重复了多次实验，统计了上千株豌豆。他提出假说：遗传因子（基因）成对存在，显性因子（D）掩盖隐性因子（d），形成配子时成对因子分离。",
      "blocks": [
        {
          "id": "b_monohybrid_result",
          "type": "flow",
          "intent": "展示 P 代（DD × dd）→ F1（Dd）→ F1 自交 → F2（1DD:2Dd:1dd，表型 3:1）的流程。"
        }
      ]
    },
    {
      "id": "dihybrid-experiment",
      "kind": "content",
      "eyebrow": "孟德尔的实验与推理",
